async def act(page):
    import csv, io, os, asyncio

    # Scope the export controls precisely per accessibility tree
    export_cell = page.get_by_role("cell", name="Export to: CSV Export")

    # Ensure CSV is selected in the combobox if present (defensive)
    combobox = export_cell.get_by_role("combobox")
    if await combobox.count() > 0:
        try:
            # prefer selecting by visible label
            await combobox.nth(0).select_option(label="CSV")
        except Exception:
            # ignore if it fails because CSV already selected or control is custom
            pass

    # Locate the Export button using the full .get_by_role path as required
    export_btn = export_cell.get_by_role("button", name="Export")
    if await export_btn.count() == 0:
        # fallback to any Export button on the page
        buttons = page.get_by_role("button")
        found = False
        for i in range(await buttons.count()):
            txt = await buttons.nth(i).inner_text()
            if "Export" in txt:
                export_btn = buttons.nth(i)
                found = True
                break
        if not found:
            raise RuntimeError("Export button not found")

    btn = export_btn.nth(0)
    # Make sure it is in view and try the click while capturing the download
    await btn.scroll_into_view_if_needed()
    async with page.expect_download(timeout=120000) as dl_info:
        # click with a generous timeout; force not used to respect accessible interaction
        await btn.click(timeout=120000)
    download = await dl_info.value

    # Save download to a file (avoid overwriting existing file)
    download_path = "sales_orders_export.csv"
    base = download_path
    idx = 1
    while os.path.exists(download_path):
        download_path = f"{os.path.splitext(base)[0]}_{idx}{os.path.splitext(base)[1]}"
        idx += 1
    await download.save_as(download_path)

    # Read and decode the CSV
    with open(download_path, 'rb') as f:
        data = f.read()
    try:
        text = data.decode('utf-8')
    except Exception:
        text = data.decode('latin-1')

    # Parse CSV and compute completed orders per customer (Bill to Name)
    rdr = csv.reader(io.StringIO(text))
    try:
        header = next(rdr)
    except StopIteration:
        raise RuntimeError("Exported CSV is empty")

    headers_lower = [h.lower() for h in header]
    # Find status and bill-to name columns heuristically
    status_idx = None
    bill_to_idx = None
    for i, h in enumerate(headers_lower):
        if 'status' in h:
            status_idx = i
        if 'bill to name' in h or ("bill" in h and "name" in h):
            bill_to_idx = i
    # fallback for bill_to_idx
    if bill_to_idx is None:
        for i, h in enumerate(headers_lower):
            if 'customer' in h and 'name' in h:
                bill_to_idx = i
                break
    if status_idx is None:
        raise RuntimeError("Could not find Status column in exported orders CSV")
    if bill_to_idx is None:
        # fallback to a reasonable default index (grid typically has Bill to Name at index 4)
        bill_to_idx = min(len(header) - 1, 4)

    counts = {}
    for row in rdr:
        if status_idx >= len(row):
            continue
        status = row[status_idx].strip().lower()
        if 'complete' not in status:
            continue
        name = row[bill_to_idx].strip() if bill_to_idx < len(row) else ''
        if not name:
            # try to find ship to name
            for i, h in enumerate(headers_lower):
                if 'ship to name' in h or ('ship' in h and 'name' in h):
                    if i < len(row):
                        name = row[i].strip()
                        break
        if not name:
            # skip if no usable customer identifier
            continue
        counts[name] = counts.get(name, 0) + 1

    if not counts:
        raise RuntimeError("No completed orders found in exported CSV")

    # Choose top customer (highest count, tie-breaker by name)
    top_customer = max(counts.items(), key=lambda kv: (kv[1], kv[0]))[0]

    # Return the top customer's name only (caller expects the single-name result)
    return top_customer

